Inductive bfact : Type :=
| BRange (id : nat) (from to : expr) (lo hi : Z)
| BSome (id : nat) (from to : expr) (lo hi : Z)
| BBad (id : nat) (s : expr) (ilo ihi : Z) (f : nat)
| BFam (id : nat) (es ee : expr) (f : nat)
| BNe (id : nat) (j : expr) (v : Z).
