Definition of_lit_region (r : SR.region) : region := let '(rb, rlo, rlen) := r in (rb, rlo, ELit rlen).
Definition region_vars_lt (n : nat) (r : region) : bool :=
  let '(rb, _, rlen) := r in (APC.expr_vars_lt n rb && APC.expr_vars_lt n rlen)%bool.
