Record INV2 (E : env) (ss : sym_state) (R : bvmap 5 word) (Mc : word -> option byte) : Prop := MKINV2 {
  i_regs : regs_ok E (s_regs ss) R;
  i_know : know_ok segs E Mc (s_know ss);
