Lemma same_range_sound : forall E M fk sb sk ne b o n,
  know_ok segs E M fk -> same_range fk sb sk ne b o n = true ->
  estart E (SA sb sk) = estart E (SA b o) /\ elenZ E ne = elenZ E n.
Proof.
