  INV2 E ss R Mc -> entails_hx lo hi ss T = true -> (nx0 <= lo)%nat -> length (s_regs T) = 32%nat ->
  (nx0 <= s_next T)%nat ->
  exists E', env_agree lo E E' /\ (forall n, (hi <= n)%nat -> ev E' n = ev E n) /\ INV2 E' T R Mc
             /\ s_pc T = s_pc ss.
