  know_ok segs E M kn -> region_flat_chkX kn r = true ->
  let '(rb, rlo, rlen) := r in 0 <= estart E (SA rb rlo) /\ 0 < elenZ E rlen < 2 ^ 64 /\ estart E (SA rb rlo) + elenZ E rlen <= 2 ^ 64.
